124	// LM transport (F1): hart-0 local-memory slave-port windows (AE350 memmap).
125	// When ilm_size/dlm_size/hvm_size are non-zero the drain also captures that
126	// many bytes of ILM/DLM/HVM CONTENT into raw sidecar files
127	// "<outfile>.ilm"/".dlm"/".hvm", for the vsim leg's --ilm/--dlm/--hvm
128	// backdoor load. The LM slave-port aperture is used (never the hart-local
129	// view: its ILM base 0x0 is also DRAM 0x0); HVM has only the one aperture
130	// (plain RAM at hvm_base, no enable bit). Size 0 (the default) = the paired
131	// engine has no such memory -> nothing read, no file written.
132	static uint64_t ilm_base_arg = 0xA0000000ull;
133	static uint64_t dlm_base_arg = 0xA0200000ull;
134	static uint64_t hvm_base_arg = 0x90000000ull;
135	static uint64_t ilm_size_arg;
136	static uint64_t dlm_size_arg;
137	static uint64_t hvm_size_arg;
138	
139	// Forwarded driver verbosity (plugin arg `log_level=N`, vsim's spdlog scale:
140	// 0=trace 1=debug 2=info ... 6=off). Chatter prints only at <= debug.
141	static uint64_t log_level_arg = 2;
142	static volatile int oracle_armed;
143	
144	// v6: which mask-governed config CSRs the guest has WRITTEN so far
145	// (hybrid/write_mask.h slot numbering). Marked by per-insn exec callbacks that
146	// are registered ONLY on instructions whose translate-time decode says "writes
147	// a governed CSR" -- steady-state code carries no instrumentation. Single-hart
148	// flow (like the rest of the handoff); atomics keep a future SMP guest safe.
149	static uint64_t csr_write_mask[2];
150	
151	static void on_csr_write(unsigned int vcpu_idx, void *udata)
152	{
153	    (void) vcpu_idx;
154	    const unsigned slot = (unsigned) (uintptr_t) udata;
155	    __atomic_fetch_or(&csr_write_mask[slot >> 6],
156	                      (uint64_t) 1 << (slot & 63u), __ATOMIC_RELAXED);
157	}
158	
159	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
160	{
161	    for (guint i = 0; i < regs->len; i++) {
162	        qemu_plugin_reg_descriptor *rd =
163	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
164	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
165	            return rd->handle;
166	        }
167	    }
168	    return NULL;
169	}
170	
171	// Lazily resolves register handles. The plugin's vcpu_init runs before
172	// QEMU has registered the dynamic gdb coprocessors (FPU, virtual, csr,
173	// vector), so qemu_plugin_get_registers() returns only the 33 core CPU
174	// regs at that moment. By the time the entry trigger fires, all dynamic
175	// features are registered and a fresh call returns the full list.
176	static void resolve_handles(VcpuRegs *v)
177	{
178	    g_autoptr(GArray) regs = qemu_plugin_get_registers();
179	    for (int i = 0; i < 32; i++) {
180	        v->gpr[i] = find_reg(regs, hybrid_gpr_names[i]);
181	        v->fpr[i] = find_reg(regs, hybrid_fpr_names[i]);
182	    }
183	    v->fcsr = find_reg(regs, "fcsr");
184	    v->pc = find_reg(regs, "pc");
185	    v->priv = find_reg(regs, "priv");
186	
187	    v->mstatus  = find_reg(regs, "mstatus");
188	    v->mepc     = find_reg(regs, "mepc");
189	    v->mtvec    = find_reg(regs, "mtvec");
190	    v->mcause   = find_reg(regs, "mcause");
191	    v->mtval    = find_reg(regs, "mtval");
192	    v->mscratch = find_reg(regs, "mscratch");
193	    v->medeleg  = find_reg(regs, "medeleg");
194	    v->mideleg  = find_reg(regs, "mideleg");
195	    v->mip      = find_reg(regs, "mip");
196	    v->mie      = find_reg(regs, "mie");
197	    v->mcycle   = find_reg(regs, "mcycle");
198	    v->minstret = find_reg(regs, "minstret");
199	    v->satp     = find_reg(regs, "satp");
200	
201	    v->mcache_ctl = find_reg(regs, "mcache_ctl");
202	    v->mmisc_ctl  = find_reg(regs, "mmisc_ctl");
203	
204	    char buf[16];
205	
206	    // Andes V5 CSR block (v3): resolve by gdb mnemonic from the shared X-macro.
207	#define HYBRID_ANDES_FIELD(field, addr, name) v->andes_##field = find_reg(regs, name);
208	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
209	#undef HYBRID_ANDES_FIELD
210	
211	    // M-ext CSR block (v4): resolve by gdb mnemonic (NULL if the stub does not
212	    // advertise it for the paired cpu).
213	#define HYBRID_M_EXT_FIELD(field, addr, name) v->m_ext_##field = find_reg(regs, name);
214	    HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
215	#undef HYBRID_M_EXT_FIELD
216	    for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
217	        // RV64 packs 8 PMA entries per cfg CSR, so only even cfg CSRs exist.
218	        g_snprintf(buf, sizeof(buf), "pmacfg%d", 2 * i);
219	        v->pmacfg[i] = find_reg(regs, buf);
220	    }
221	    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
222	        g_snprintf(buf, sizeof(buf), "pmaaddr%d", i);
223	        v->pmaaddr[i] = find_reg(regs, buf);
224	    }
225	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
226	        g_snprintf(buf, sizeof(buf), "pmpcfg%d", i);
227	        v->pmpcfg[i] = find_reg(regs, buf);
228	    }
229	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
230	        g_snprintf(buf, sizeof(buf), "pmpaddr%d", i);
231	        v->pmpaddr[i] = find_reg(regs, buf);
232	    }
233	
234	    v->vstart = find_reg(regs, "vstart");
235	    v->vxsat  = find_reg(regs, "vxsat");
236	    v->vxrm   = find_reg(regs, "vxrm");
237	    v->vcsr   = find_reg(regs, "vcsr");
238	    v->vtype  = find_reg(regs, "vtype");
239	    v->vl     = find_reg(regs, "vl");
240	    v->vlenb  = find_reg(regs, "vlenb");
241	    for (int i = 0; i < 32; i++) {
242	        g_snprintf(buf, sizeof(buf), "v%d", i);
243	        v->vreg[i] = find_reg(regs, buf);
244	    }
245	}
246	
247	static uint64_t read_reg64(struct qemu_plugin_register *h)
248	{
249	    if (!h) return 0;
250	    g_autoptr(GByteArray) buf = g_byte_array_new();
251	    int sz = qemu_plugin_read_register(h, buf);
252	    if (sz <= 0) return 0;
253	    uint64_t v = 0;
254	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
255	    return v;
256	}
257	
258	// Reads up to `dst_max` bytes from a register handle. Returns the byte
259	// count written (0 on failure or NULL handle). Used for vector regs whose
260	// width = vlenb bytes.
261	static size_t read_reg_bytes(struct qemu_plugin_register *h,
262	                             uint8_t *dst, size_t dst_max)
263	{
264	    if (!h || dst_max == 0) return 0;
265	    g_autoptr(GByteArray) buf = g_byte_array_new();
266	    int sz = qemu_plugin_read_register(h, buf);
267	    if (sz <= 0) return 0;
268	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
269	    memcpy(dst, buf->data, n);
270	    return n;
271	}
272	
273	// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
274	// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
275	// O_EXCL-style inode reservation, so concurrent plugin instances cannot
276	// collide even under aggressive PID reuse (B13). The tmp lives in the
277	// same directory as `path` so the rename is intra-filesystem.
278	static int write_blob_atomic(const void *data, size_t len, const char *path)
279	{
280	    char tmp[PATH_MAX];
281	    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
282	    if (n < 0 || (size_t) n >= sizeof(tmp)) {
283	        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
284	        return -1;
285	    }
286	    int fd = g_mkstemp(tmp);
287	    if (fd < 0) {
288	        perror("hybrid_handoff: g_mkstemp");
289	        return -1;
290	    }
291	    // g_mkstemp creates the file 0600; no further chmod needed.
292	    ssize_t got = write(fd, data, len);
293	    if (got != (ssize_t) len) {
294	        perror("hybrid_handoff: write");
295	        close(fd);
296	        unlink(tmp);
297	        return -1;
298	    }
299	    fsync(fd);
300	    close(fd);
301	    if (rename(tmp, path) != 0) {
302	        perror("hybrid_handoff: rename");
303	        unlink(tmp);
304	        return -1;
305	    }
306	    return 0;
307	}
308	
309	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
310	{
311	    return write_blob_atomic(s, sizeof(*s), path);
312	}
313	
314	// Drain CPU state into `*s`. pc is computed by the caller (from a
315	// HandoffSite for trigger paths).
316	static void drain_state_into(unsigned int vcpu_idx, uint64_t pc,
317	                             struct hybrid_state_v1 *sp)
318	{
319	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
320	    resolve_handles(v);
321	    memset(sp, 0, sizeof(*sp));
322	    struct hybrid_state_v1 s = {0};
323	    s.magic   = HYBRID_STATE_MAGIC;
324	    s.version = HYBRID_STATE_VERSION;
325	    s.flags   = HYBRID_FLAG_RV64;
326	    s.hart_id = vcpu_idx;
327	    // L6: real privilege at the boundary; M-mode fallback only when the
328	    // stub doesn't advertise the gdbstub virtual feature (a missing handle
329	    // reads as 0 = U, which would silently demote the hart).
330	    s.priv    = v->priv ? (read_reg64(v->priv) & 0x3) : 3;
331	    s.pc      = pc;
332	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
333	
334	    // Floating-point: only set FP flag if at least one handle was bound,
335	    // i.e. QEMU advertised the FPU feature (D extension).
336	    int has_fp = 0;
337	    for (int i = 0; i < 32; i++) {
338	        s.fpr[i] = read_reg64(v->fpr[i]);
339	        if (v->fpr[i]) has_fp = 1;
340	    }
341	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
342	    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP
343	
344	    s.mstatus  = read_reg64(v->mstatus);
345	    s.mepc     = read_reg64(v->mepc);
346	    s.mtvec    = read_reg64(v->mtvec);
347	    s.mcause   = read_reg64(v->mcause);
348	    s.mtval    = read_reg64(v->mtval);
349	    s.mscratch = read_reg64(v->mscratch);
350	    s.medeleg  = read_reg64(v->medeleg);
351	    s.mideleg  = read_reg64(v->mideleg);
352	    s.mip      = read_reg64(v->mip);
353	    s.mie      = read_reg64(v->mie);
354	    s.mcycle   = read_reg64(v->mcycle);
355	    s.minstret = read_reg64(v->minstret);
356	    s.satp     = read_reg64(v->satp);
357	
358	    // Andes cache fix: carry crt0's cache-enable so the cycle engine resumes
359	    // with caches on (NULL handle on a non-Andes stub reads back as 0).
360	    s.mcache_ctl = read_reg64(v->mcache_ctl);
361	    s.mmisc_ctl  = read_reg64(v->mmisc_ctl);
362	
363	    // Andes V5 CSR block (v3): drain every transported Andes CSR. Set
364	    // HYBRID_FLAG_ANDES if the stub advertised at least one (mirrors has_fp/
365	    // has_v); otherwise the block stays zero and consumers skip it. A NULL
366	    // handle on a non-Andes stub reads back as 0 -> tolerant.
367	    int has_andes = 0;
368	#define HYBRID_ANDES_FIELD(field, addr, name)  \
369	    s.andes.field = read_reg64(v->andes_##field); \
370	    if (v->andes_##field) has_andes = 1;
371	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
372	#undef HYBRID_ANDES_FIELD
373	    for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
374	        s.andes.pmacfg[i] = read_reg64(v->pmacfg[i]);
375	        if (v->pmacfg[i]) has_andes = 1;
376	    }
377	    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
378	        s.andes.pmaaddr[i] = read_reg64(v->pmaaddr[i]);
379	        if (v->pmaaddr[i]) has_andes = 1;
380	    }
381	    if (has_andes) s.flags |= HYBRID_FLAG_ANDES;
382	
383	    // M-ext CSR block (v4): drain every transported M-mode CSR the stub
384	    // advertised. Set HYBRID_FLAG_M_EXT if at least one resolved; a NULL handle
385	    // reads 0. The vsim caps gate decides which of these the cycle engine
386	    // actually restores, so draining an absent-on-vsim CSR here is harmless.
387	    int has_m_ext = 0;
388	#define HYBRID_M_EXT_FIELD(field, addr, name)  \
389	    s.m_ext.field = read_reg64(v->m_ext_##field); \
390	    if (v->m_ext_##field) has_m_ext = 1;
391	    HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
392	#undef HYBRID_M_EXT_FIELD
393	    if (has_m_ext) s.flags |= HYBRID_FLAG_M_EXT;
394	
395	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
396	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
397	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
398	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
399	
400	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
401	    // bounds the per-register byte count copied into vreg[]. The policy
402	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
403	    // handle truthiness so we don't conflate "stub missing vlenb" with
404	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
405	    s.vstart = read_reg64(v->vstart);
406	    s.vxsat  = read_reg64(v->vxsat);
407	    s.vxrm   = read_reg64(v->vxrm);
408	    s.vcsr   = read_reg64(v->vcsr);
409	    s.vtype  = read_reg64(v->vtype);
410	    s.vl     = read_reg64(v->vl);
411	    s.vlenb  = read_reg64(v->vlenb);
412	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
413	                       || v->vtype || v->vl);
414	    if (!has_other_v) {
415	        for (int i = 0; i < 32; i++)
416	            if (v->vreg[i]) { has_other_v = 1; break; }
417	    }
418	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
419	        v->vlenb != NULL, has_other_v, s.vlenb);
420	    if (vpol == HYBRID_V_DRAIN_ABORT) {
421	        if (v->vlenb == NULL)
422	            fprintf(stderr,
423	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
424	                    "vlenb; refusing to drain partial V state\n");
425	        else
426	            fprintf(stderr,
427	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
428	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
429	                    "truncate V registers\n",
430	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
431	                    8 * HYBRID_VLEN_BYTES_MAX);
432	        exit(2);
433	    }
434	    if (vpol == HYBRID_V_DRAIN_OK) {
435	        s.flags |= HYBRID_FLAG_V;
436	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
437	         * full live register fits the wire-format slot -- no clamp (L11). */
438	        for (int i = 0; i < 32; i++)
439	            (void) read_reg_bytes(v->vreg[i],
440	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
441	                                  (size_t) s.vlenb);
442	    }
443	
444	    // v6: which mask-governed CSRs the guest actually wrote (translate-time
445	    // decode + exec callbacks above). ucode rides transport-always: DSP
446	    // instructions update its sticky OV flag without any CSR instruction, so
447	    // instruction-level tracking cannot see those writes (like fcsr's fflags).
448	    s.write_mask[0] = __atomic_load_n(&csr_write_mask[0], __ATOMIC_RELAXED);
449	    s.write_mask[1] = __atomic_load_n(&csr_write_mask[1], __ATOMIC_RELAXED);
450	    hybrid_wm_set(s.write_mask, HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_ucode);
451	    s.flags |= HYBRID_FLAG_WRITE_MASK;
452	
453	    // v5: L2C MMIO register window (DS220 11.8.5 Table 112, offsets
454	    // 0x0000..0x0527). Read the whole documented block from the L2C base by
455	    // PHYSICAL address (paging is off in the M-mode boot flow, so VA==PA anyway).
456	    // QEMU's AE350 machine maps L2C as a device region; if the read fails (a
457	    // machine without an L2C), the flag stays clear and consumers skip the
458	    // block. Little-endian native host, so the raw bytes land directly in
459	    // s.l2c.reg[]. The vsim side gates restore on its OWN L2C presence, so
460	    // setting the flag whenever QEMU can read the region is correct.
461	    {
462	        g_autoptr(GByteArray) l2c = g_byte_array_new();
463	        enum qemu_plugin_hwaddr_operation_result r =
464	            qemu_plugin_read_memory_hwaddr(l2c_base_arg, l2c,
465	                                           HYBRID_L2C_REG_WINDOW_BYTES);
466	        if (r == QEMU_PLUGIN_HWADDR_OPERATION_OK
467	            && l2c->len == HYBRID_L2C_REG_WINDOW_BYTES) {
468	            memcpy(s.l2c.reg, l2c->data, HYBRID_L2C_REG_WINDOW_BYTES);
469	            s.flags |= HYBRID_FLAG_L2C;
470	        }

