// One-off: prove hybrid_state_v1 has zero padding bytes by comparing
// sizeof(struct) with the sum of all member sizes.
#include <stdio.h>
#include <stddef.h>
#include "hybrid/state_abi.h"

#define M(f) sizeof(((struct hybrid_state_v1 *)0)->f)

int main(void)
{
    size_t sum =
        M(magic) + M(version) + M(flags) + M(hart_id) + M(pc) + M(priv) +
        M(gpr) + M(fpr) +
        M(mstatus) + M(mepc) + M(mtvec) + M(mcause) + M(mtval) +
        M(mscratch) + M(medeleg) + M(mideleg) + M(mip) + M(mie) +
        M(mcycle) + M(minstret) + M(satp) +
        M(pmpcfg) + M(pmpaddr) +
        M(vstart) + M(vtype) + M(vl) + M(vlenb) + M(vreg) +
        M(vxsat) + M(vxrm) + M(vcsr) + M(fcsr) +
        M(mcache_ctl) + M(mmisc_ctl) +
        M(andes) + M(m_ext) + M(l2c) + M(write_mask) + M(reserved);
    printf("sizeof=%zu sum=%zu -> %s\n", sizeof(struct hybrid_state_v1), sum,
           sizeof(struct hybrid_state_v1) == sum ? "NO PADDING" : "HAS PADDING");
    return sizeof(struct hybrid_state_v1) != sum;
}

